/* Values travel as a count byte then, per value: a type byte (1 bool, 2 int, 3 float, 4 string, 5 handle, 6 list) and
   its bytes; see the Value codec in source/mod/ModValue.cpp. A list, the result written list:handle, is a length of four
   bytes and then that many bytes: a count of four bytes and each item packed as a value here. */

int lce_pack_int(uint8_t* out, int64_t value);
int lce_pack_float(uint8_t* out, double value);
int lce_pack_bool(uint8_t* out, int value);
int lce_pack_string(uint8_t* out, const char* text, int length);
int lce_pack_handle(uint8_t* out, lce_handle handle);

#ifdef LCE_IMPLEMENTATION
int lce_pack_int(uint8_t* out, int64_t v) { out[0] = 2; memcpy(out + 1, &v, 8); return 9; }
int lce_pack_float(uint8_t* out, double v) { out[0] = 3; memcpy(out + 1, &v, 8); return 9; }
int lce_pack_bool(uint8_t* out, int v) { out[0] = 1; out[1] = v != 0; return 2; }
int lce_pack_string(uint8_t* out, const char* t, int n) { out[0] = 4; memcpy(out + 1, &n, 4); memcpy(out + 5, t, n); return 5 + n; }
int lce_pack_handle(uint8_t* out, lce_handle h) { uint64_t id = h.id; out[0] = 5; out[1] = (uint8_t)h.kind; memcpy(out + 2, &id, 8); return 10; }
#endif

#endif
